namespace sv_0c4af61480114329b17c7384f5ff87b1.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) });
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) });
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) });
    }

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_lock)
        {
            var newer = _notifications.Where(n => n.Id > lastId).ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Call this periodically or from a background service.
    /// </summary>
    public Task<NotificationItem?> SimulateIncomingAsync()
    {
        // ~30% chance a new notification arrives each poll
        if (Random.Shared.Next(100) < 30)
        {
            var item = new NotificationItem
            {
                Timestamp = DateTime.UtcNow,
                Message = $"New event at {DateTime.UtcNow:HH:mm:ss} — item #{Random.Shared.Next(1000)}"
            };

            lock (_lock)
            {
                item.Id = _nextId++;
                _notifications.Add(item);
            }

            return Task.FromResult<NotificationItem?>(item);
        }

        return Task.FromResult<NotificationItem?>(null);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using sv_0c4af61480114329b17c7384f5ff87b1.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var item in notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item">
                <strong>@item.Timestamp.ToString("HH:mm:ss")</strong> &mdash; @item.Message
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem>? PersistedNotifications { get; set; }

    private List<NotificationItem> notifications = new();
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip re-fetching
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate new notifications arriving
            await NotificationService.SimulateIncomingAsync();

            var newer = await NotificationService.GetNotificationsSinceAsync(lastId);
            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                lastId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

