@code {
    private const string PersistenceKey = "notifications";
    private List<NotificationItem> notifications = new();
    private PersistingComponentStateSubscription _persistSub;
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (!ApplicationState.TryTakeFromJson<List<NotificationItem>>(PersistenceKey, out var restored))
        {
            notifications = await NotificationService.GetNotificationsAsync();
        }
        else
        {
            notifications = restored!;
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson(PersistenceKey, notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate new notifications arriving
            await NotificationService.SimulateIncomingAsync();

            var newer = await NotificationService.GetNotificationsSinceAsync(lastId);
            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                lastId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

